// ═══════════════════════════════════════════════════════════════
// WHATSAPP PARSER v5 — case-insensitive contact extraction
// Handles lowercase names from voice transcription
// ═══════════════════════════════════════════════════════════════

const input = $input.first().json;
const userRequest = String(input.query || input.user_request || input.message || input.text || JSON.stringify(input));

console.log('[WhatsApp] Raw input:', JSON.stringify(input));
console.log('[WhatsApp] User request:', userRequest);

const request = userRequest.toLowerCase();

let action  = 'send_message';
let contact = '';
let message = '';
let match;

// Common non-name words to exclude from contact extraction
const SKIP_WORDS = new Set([
  'the','a','an','my','our','your','him','her','them','me','us','it',
  'on','in','at','for','from','is','are','was','how','what','where',
  'when','who','please','right','now','today','tonight','tomorrow',
  'and','but','or','whatsapp','message','msg','send','text','tell',
  'ask','hi','hey','any','new','last','recent','check','show','get',
  'inbox','read','retrieve','retrive','saying','say','that','did','got'
]);

function cleanContact(name) {
  if (!name) return '';
  // Capitalize each word
  return name.trim().split(/\s+/)
    .filter(w => w.length > 1 && !SKIP_WORDS.has(w.toLowerCase()))
    .map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
    .join(' ');
}

// ── STEP 1: Detect action type ────────────────────────────────

const isReadRequest =
  request.includes('read') ||
  request.includes('retrive') ||
  request.includes('retrieve') ||
  request.includes('what message') ||
  request.includes('what did') ||
  request.includes('sent me') ||
  request.includes('sended me') ||
  request.includes('received') ||
  request.includes('show me') ||
  request.includes('check message') ||
  request.includes('any message') ||
  request.includes('new message') ||
  request.includes('recent message') ||
  request.includes('last message') ||
  request.includes('inbox');

const isCallRequest =
  request.includes('call') &&
  !request.includes('saying') &&
  !request.includes('say');

if (isReadRequest && (request.includes('message') || request.includes('chat') || request.includes('whatsapp') || request.includes('inbox') || request.includes('retrive') || request.includes('retrieve'))) {
  action = 'read_messages';
} else if (isCallRequest) {
  action = 'voice_call';
}

// ── STEP 2: Extract contact — case-insensitive patterns ───────
// KEY FIX: removed [A-Z] uppercase requirement — works with lowercase voice input

// Pattern A: "to [NAME] saying"
match = userRequest.match(/\bto\s+((?:[A-Za-z]+\s+){0,2}[A-Za-z]+)\s+saying\b/i);
if (match) {
  const c = cleanContact(match[1]);
  if (c) { contact = c; console.log('[WhatsApp] Contact via A:', contact); }
}

// Pattern B: "message/text/tell [NAME] saying"
if (!contact) {
  match = userRequest.match(/\b(?:message|text|tell|whatsapp)\s+((?:[A-Za-z]+\s+){0,2}[A-Za-z]+)\s+saying\b/i);
  if (match) {
    const c = cleanContact(match[1]);
    if (c) { contact = c; console.log('[WhatsApp] Contact via B:', contact); }
  }
}

// Pattern C: "to [name]" — stops before common verbs/prepositions
if (!contact) {
  match = userRequest.match(/\bto\s+([A-Za-z]+(?:\s+[A-Za-z]+){0,1})(?:\s+(?:saying|on|in|via|about|that|the)|$)/i);
  if (match) {
    const c = cleanContact(match[1]);
    if (c) { contact = c; console.log('[WhatsApp] Contact via C:', contact); }
  }
}

// Pattern D: "send/text/tell [name]"
if (!contact) {
  match = userRequest.match(/\b(?:send|text|tell|whatsapp)\s+([A-Za-z]+(?:\s+[A-Za-z]+){0,1})(?:\s|$)/i);
  if (match) {
    const c = cleanContact(match[1]);
    if (c) { contact = c; console.log('[WhatsApp] Contact via D:', contact); }
  }
}

// Pattern E: "Hey/Hi [name]," — pre-composed message
if (!contact) {
  match = userRequest.match(/^(?:hey|hi|hello|dear|yo)\s+([A-Za-z]+(?:\s+[A-Za-z]+){0,1})[,!\s]/i);
  if (match) {
    const c = cleanContact(match[1]);
    if (c) {
      contact = c;
      message = userRequest;
      console.log('[WhatsApp] Contact via E:', contact);
    }
  }
}

// Pattern F: "Ask/Tell/Remind [name] [message]"
if (!contact) {
  match = userRequest.match(/^(?:ask|tell|inform|notify|remind)\s+([A-Za-z]+(?:\s+[A-Za-z]+){0,1})\s+(.+)/i);
  if (match) {
    const c = cleanContact(match[1]);
    if (c) {
      contact = c;
      message = match[2].trim();
      console.log('[WhatsApp] Contact via F:', contact);
    }
  }
}

// Pattern G: read requests — "from [name]", "[name] sent", "message from [name]"
if (!contact && action === 'read_messages') {
  match = userRequest.match(/\bfrom\s+([A-Za-z]+(?:\s+[A-Za-z]+){0,1})/i);
  if (!match) match = userRequest.match(/\b([A-Za-z]+)\s+(?:sent|sended|send)/i);
  if (!match) match = userRequest.match(/\bby\s+([A-Za-z]+)/i);
  if (!match) {
    // "check neel messages", "neel whatsapp" — name before keyword
    match = userRequest.match(/\b([A-Za-z]+)\s+(?:message|whatsapp|chat)/i);
  }
  if (match) {
    const c = cleanContact(match[1]);
    if (c) { contact = c; console.log('[WhatsApp] Contact via G:', contact); }
  }
}

// ── STEP 3: Message extraction (skip if set by E or F) ────────

if (!message) {
  match = userRequest.match(/\bsaying\s+(.+)$/i);
  if (match) { message = match[1].trim(); }

  if (!message) {
    match = userRequest.match(/\bsay\s+(.+)$/i);
    if (match) { message = match[1].trim(); }
  }

  if (!message) {
    match = userRequest.match(/\bthat\s+(.+)$/i);
    if (match) { message = match[1].trim(); }
  }

  if (!message && contact) {
    const escaped = contact.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const after = userRequest
      .replace(new RegExp(`.*?\\b${escaped}\\b`, 'i'), '')
      .replace(/^\s*(saying|say|that|to|message|,|-)\s*/i, '')
      .trim();
    if (after.length > 1) { message = after; }
  }

  if (!message) { message = userRequest; }
}

// ── OUTPUT ────────────────────────────────────────────────────

const result = {
  action,
  contact: contact || 'Unknown',
  message: message || userRequest
};

console.log('[WhatsApp] ✅ Final:', JSON.stringify(result));
return result;

const input = $input.first().json;

let response;

if (input.success) {
  // For read_messages, format the messages nicely
  if (input.messages && Array.isArray(input.messages) && input.messages.length > 0) {
    const formatted = input.messages.map((m, i) => `${i+1}. ${m}`).join('\n');
    response = `Recent messages:\n${formatted}`;
  } else {
    response = input.message || 'WhatsApp action completed successfully';
  }
} else {
  response = `WhatsApp error: ${input.error || 'Unknown error'}`;
}

console.log('[WhatsApp] Response:', response);
return { result: response };
